from __future__ import annotations

from pydantic import Field
from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, SdkBaseModel


class Run(SdkBaseModel):
    run_id: Optional[str] = Field(default=UNSET, alias="runId")
    """The runId of a workflow execution. This ID is generated by the service and can be used to uniquely identify the
    workflow execution within a domain."""


class RunDict(TypedDict):
    run_id: NotRequired[str]
